TWISTED_EXT_HELP = [
    "# twisted_ext - توسعة حزمة twisted: أصنافها ودوالها وطرقها وثوابتها التي لا تغطّيها مكتبات APL الأخرى",
]

_TWISTED_EXT_TOKEN = re.compile(
    r"(?P<dot>\.)?"
    r"(?P<word>(?!\d)[\w\u064B-\u065F\u0670]+)"
    r"(?P<open>\s*\()?"
)

USER_NAMES = set()


def _twisted_ext_replace(match):
    dot = match.group("dot")
    word = match.group("word")
    open_paren = match.group("open")
    if word in USER_NAMES:
        return match.group(0)
    if dot:
        return match.group(0)
    if word in TWISTED_EXT_CONSTS:
        return TWISTED_EXT_CONSTS[word]
    if word in TWISTED_EXT_FUNCS:
        return TWISTED_EXT_FUNCS[word] + (open_paren or "")
    return match.group(0)


def TWISTED_EXT_SUBSTITUTE(text):
    """يترجم كلمات المكتبة في نص واحد ويُرجع المترجم."""
    if not text:
        return text
    return _TWISTED_EXT_TOKEN.sub(_twisted_ext_replace, text)
